'use strict';
// All controls come from the server's integer-cent report. Models only explain.
function pdfCheckMoney(value){return value==null?'Nicht erkannt':money(value);}
function pdfCheckMarkup(c){
 const diff=c.difference_cents;
 const explanation=diff==null?c.explanation:diff===0?(c.mismatch?'Der Endstand passt. Bei den Umsatzsummen gibt es eine Abweichung; die Tabelle zeigt dir genau welche.':c.explanation):`Deine Liste endet ${money(Math.abs(diff))} ${diff>0?'unter':'über'} dem gelesenen Endstand. Prüfe die Zahlungszeilen und die Kontrollwerte im Original.`;
 const comparisons=[['Geldeingänge',c.credit_cents,c.incoming_cents,c.credit_difference_cents],['Geldausgänge',c.debit_cents,c.outgoing_cents,c.debit_difference_cents],['Endstand',c.closing_cents,c.calculated_closing_cents,diff]];
 return `<section class="pdf-control-group"><p class="small muted">${c.key==='document'?'Gesamter Auszug':c.key==='other'?'Weitere PDF-Seiten':'Auszug '+esc(c.key)} · PDF-Seiten ${c.pages.join(', ')}${c.months.length>1?` · gemeinsamer Abgleich für ${c.months.map(pdfMonthLabel).map(esc).join(', ')}`:''}</p><p class="pdf-control-explanation">${esc(explanation)}</p>${(c.page_links||[]).map(link=>`<p class="small muted">${esc(link.message)} <span>(${esc(link.quote)})</span></p>`).join('')}<div class="pdf-equation"><span>Anfangsstand<strong>${pdfCheckMoney(c.opening_cents)}</strong></span><b>+</b><span>Eingänge<strong>${money(c.incoming_cents)}</strong></span><b>−</b><span>Ausgänge<strong>${money(c.outgoing_cents)}</strong></span><b>=</b><span>Errechneter Endstand<strong>${pdfCheckMoney(c.calculated_closing_cents)}</strong></span></div><div class="pdf-compare-wrap"><table class="pdf-compare pdf-control-table"><caption>Kontrollwerte aus dem PDF und deine aktuelle Zahlungsliste</caption><thead><tr><th>Kontrolle</th><th>Im PDF gelesen</th><th>Deine Liste</th><th>Differenz</th></tr></thead><tbody>${comparisons.map(([label,original,actual,difference])=>`<tr${difference!=null&&difference!==0?' class="is-different"':''}><th>${label}</th><td>${pdfCheckMoney(original)}</td><td>${pdfCheckMoney(actual)}</td><td>${difference==null?'Kein Vergleich':money(difference)}</td></tr>`).join('')}</tbody></table></div><p class="small muted">Differenz = PDF-Kontrollwert minus Liste. Private Zahlungen und „schon erfasst“ zählen beim Bankabgleich mit. Ausgeschlossene Gebühren-Details zählen nicht mit.</p>${c.hints.length?`<div class="pdf-possible-causes"><strong>Mögliche Ursache · bitte nachsehen</strong>${c.hints.map(h=>`<p>${esc(h.message)} ${button('Zahlung auf Seite '+h.page+' ansehen','jump-pdf-index','','text-link',`data-index="${h.index}"`)}</p>`).join('')}</div>`:''}${c.mismatch?'<p class="small">Prüfe auch die gelesenen Anfangs- und Endstände sowie die Umsatzsummen im Original. Eine Abweichung beweist für sich allein keine falsche Zahlung.</p>':''}${c.opening_cents_quote||c.closing_cents_quote||c.credit_cents_quote||c.debit_cents_quote?`<details class="source-details"><summary>Gelesene Originalstellen der Kontrollwerte</summary><pre class="pdf-source-text">${esc([...new Set([c.opening_cents_quote,c.closing_cents_quote,c.credit_cents_quote,c.debit_cents_quote].filter(Boolean))].join('\n'))}</pre></details>`:''}</section>`;
}
function renderPdfReconciliation(form,review){
 if(!form.isConnected)return;app.pdfReconciliation=review;
 const status=$('#pdf-review-status',form);status.textContent=`${review.pending_count} ${review.pending_count===1?'Monat offen':'Monate offen'} · ${review.approved_count} übernommen. Der Abgleich bezieht sich auf deine aktuelle Liste.`;status.classList.remove('error-text');
 for(const m of review.months){
  if(m.status==='approved')continue;
  let section=[...form.querySelectorAll('#pdf-rows > .pdf-month')].find(s=>s.dataset.month===m.month);
  if(!section){section=document.createElement('section');section.className='pdf-month';section.dataset.month=m.month;section.innerHTML=`<header class="pdf-month-head"><div><h3>${esc(pdfMonthLabel(m.month))}</h3><span class="pdf-month-totals small muted">Im Original vorhanden</span></div><span class="pdf-month-status tag"></span></header><div class="pdf-month-check"></div>`;$('#pdf-rows',form).append(section);}
  const checks=review.checks.filter(c=>m.checks.includes(c.key)),tag=$('.pdf-month-status',section);
  tag.textContent={ok:'Kontrollwerte passen',difference:'Abweichung ansehen',blocked:'Zahlungen abgleichen',unverified:'Am Original prüfen'}[m.status];tag.className='pdf-month-status tag '+(m.status==='ok'?'green':'amber');
  const box=$('.pdf-month-check',section),signature=JSON.stringify([m,checks]);if(box.dataset.signature===signature){box.classList.remove('is-outdated');continue;}box.dataset.signature=signature;
  const override=app.pdfOverrides[m.month]||{};
  box.innerHTML=`<details class="pdf-reconciliation-details"${m.status!=='ok'?' open':''}><summary>${m.status==='ok'?'Rechenprüfung ansehen':'Was stimmt noch nicht?'}</summary>${checks.map(pdfCheckMarkup).join('')}${m.missing.length?`<div class="pdf-missing-sources"><strong>Diese Originalzahlungen fehlen in der Auswahl</strong>${m.missing.map((r,i)=>`<p>${esc(pdfDate(r.booked_on))} · ${money(r.amount_cents)} · ${esc(r.partner)} · Seite ${r.page}<br>${button('Originalzahlung wieder aufnehmen','add-pdf-missing','','small',`data-month="${m.month}" data-missing="${i}"`)}</p>`).join('')}</div>`:''}${m.repeated.length?`<p class="error-text">Mehrfach zugeordnet: ${m.repeated.map(r=>`${esc(pdfDate(r.booked_on))} · ${money(r.amount_cents)} · ${esc(r.partner)} · Seite ${r.page}`).join('; ')}. Lass nur die zusätzliche Kopie als „Keine eigene Zahlung“ aus.</p>`:''}${m.diagnostics.length?`<p class="error-text">${m.diagnostics.length} Zahlung(en) brauchen einen Originalabgleich. Die genaue Erklärung steht direkt bei der Zahlung. ${button('Zur Zahlung','jump-pdf-index','','small',`data-index="${m.diagnostics[0].index}"`)}</p>`:''}${m.notes.length?`<div class="pdf-reading-notes"><strong>Hinweise des ursprünglichen Lesevorgangs</strong><p class="small muted">Diese Hinweise können bereits korrigierte Angaben betreffen. Ob Datum und Betrag jetzt passen, zeigt der aktuelle Originalabgleich bei der Zahlung. Notiere unten kurz, was du geprüft hast.</p><ul>${m.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></div>`:''}<div class="pdf-check-tools">${button('PDF öffnen','pdf-original','file','small',`data-id="${app.intakeJob.document_id}"`)}${button('3 KIs um Prüfhilfe bitten','explain-pdf-month','spark','ghost small',`data-month="${m.month}"`)}</div><div class="pdf-ai-explanation" aria-live="polite"></div></details>${m.status==='difference'||m.notes.length?`<div class="pdf-override" data-month="${m.month}">${m.status==='difference'?`<label class="check"><input type="checkbox" data-override-accepted${override.accepted?' checked':''}>Trotz Abweichung übernehmen · Original selbst geprüft</label>`:''}<label>Was hast du geprüft?<textarea data-override-note maxlength="2000" rows="2" placeholder="z. B. Alle Zahlungszeilen mit dem Original verglichen. Der gelesene Endstand ist unklar; Abweichung bleibt dokumentiert.">${esc(override.note||'')}</textarea></label><p class="small muted">Die Abweichung bleibt im Prüfverlauf sichtbar. Beträge werden dabei nicht automatisch geändert.</p></div>`:''}<div class="pdf-month-approve"><span class="small muted">${m.unchosen.length?m.unchosen.length+' Einordnungen noch offen':'Einordnungen gewählt'}${!m.indices.length?' · keine Zahlung ausgewählt':''}</span>${m.month==='unknown'?'':button('Diesen Monat freigeben','approve-pdf-month','','small',`data-month="${m.month}"`)}</div>`;
  box.classList.remove('is-outdated');
 }
 const done=app.intakeJob.approvals||[],summary=$('#pdf-approved-summary',form);summary.hidden=!done.length;
 if(done.length){$('summary',summary).textContent=done.length+(done.length===1?' übernommener Monat':' übernommene Monate')+' · Prüfverlauf';$('.approved-month-list',summary).innerHTML=done.map(a=>`<article class="pdf-approved-month"><strong>${esc(pdfMonthLabel(a.month))}</strong><span class="tag ${a.report.month.status==='difference'?'amber':'green'}">${a.report.month.status==='difference'?'Mit Abweichung übernommen':a.report.month.status==='unverified'?'Am Original geprüft':'Übernommen'}</span><p class="small muted">${a.result.imported||0} neu · ${a.result.linked||0} verknüpft · ${a.result.skipped||0} ausgelassen · ${stamp(a.approved_at)}</p>${a.note?`<p>${esc(a.note)}</p>`:''}<details class="source-details"><summary>Gespeicherter Abgleich</summary>${a.report.checks.map(pdfCheckMarkup).join('')}</details></article>`).join('')+button('Zahlungen im Dashboard ansehen','pdf-approved-dashboard','arrow','small');}
 $('[type=submit]',form).hidden=!review.pending_count;
 $('.pdf-approval',form).hidden=!review.pending_count;
 if(!review.pending_count){$('.pdf-review-footer',form).hidden=true;$('.pdf-summary-strip',form).hidden=true;$('.pdf-review-help',form).textContent='Alle Monate dieses Auszugs sind übernommen. Hier findest du den gespeicherten Prüfverlauf.';summary.open=true;$('#pdf-rows',form).hidden=true;$('.pdf-secondary-actions',form).hidden=true;}
}
function markPdfChecksStale(form){if(!app.pdfReconciliation)return;$('#pdf-review-status',form).textContent='Änderungen werden gesichert und neu abgeglichen …';for(const box of form.querySelectorAll('.pdf-month-check'))box.classList.add('is-outdated');}
function schedulePdfReconciliation(form){clearTimeout(app.pdfCheckTimer);app.pdfCheckTimer=setTimeout(()=>refreshPdfReconciliation(form),250);}
async function refreshPdfReconciliation(form,focus=false){
 if(!form?.isConnected)return;clearTimeout(app.pdfCheckTimer);const seq=(app.pdfCheckSequence||0)+1;app.pdfCheckSequence=seq;const revision=app.pdfRevision;
 try{const r=await api('/api/intake/pdf-reconcile',collectPdf(form));if(seq!==app.pdfCheckSequence||revision!==app.pdfRevision||!form.isConnected)return;
  renderPdfReconciliation(form,r.review);if(r.review.diagnostics.length){showPdfDiagnostics(form,{diagnostics:r.review.diagnostics},focus);}else clearPdfDiagnostics(form);
  if(focus){const target=[...form.querySelectorAll('.pdf-month')].find(s=>r.review.months.some(m=>m.month===s.dataset.month&&m.status!=='ok'&&m.status!=='approved'));target?.scrollIntoView({block:'start'});toast('Aktuelle Zahlen und Originalzeilen geprüft.');}
 }catch(e){if(form.isConnected){const status=$('#pdf-review-status',form);status.textContent='Abgleich noch offen: '+e.message;status.classList.add('error-text');}}
}
async function approvePdfMonths(form,selected){
 const result=$('.form-result',form);if(!$('[name=checked]',form).checked){result.className='form-result form-error';result.textContent='Bitte unten bestätigen, dass du die ausgewählten Monate am Original geprüft hast.';pdfFocus($('[name=checked]',form));return;}
 const months=selected||[...new Set(collectPdf(form).rows.map(r=>pdfMonth(r.booked_on)))].filter(m=>m.startsWith(app.intakeJob.year+'-')&&!(app.intakeJob.approvals||[]).some(a=>a.month===m));
 form.inert=true;result.className='form-result';result.textContent='Ausgewählte Monate werden geprüft und gespeichert …';
 try{await queuePdfSave(form);clearTimeout(app.pdfCheckTimer);const r=await api('/api/intake/pdf-approve',{...collectPdf(form),months,checked:true});app.bankYear=null;
  if(r.needs_review){showBankPreview(r.preview);toast('Bitte noch die markierten möglichen Doppelungen prüfen.');return;}
  app.suppressDraft=true;closeModal();app.suppressDraft=false;await refresh();const remaining=r.job?.state!=='complete';
  if(remaining)pdfReviewForm(r.job);else {app.inboxMonth='';app.inboxFilter='all';navigate('inbox');}
  toast(r.already_approved?'Monat war bereits gespeichert.':`${r.result.imported} neue Zahlungen · ${r.result.linked||0} verknüpft · ${remaining?'nur offene Monate bleiben sichtbar.':'gespeichert.'}`);
 }catch(e){form.inert=false;result.className='form-result form-error';result.textContent=e.message;if(e.details?.kind==='pdf_reconciliation'){
   renderPdfReconciliation(form,e.details.review);if(e.details.review.diagnostics.length)showPdfDiagnostics(form,{diagnostics:e.details.review.diagnostics});
   const m=e.details.review.months.find(m=>months.includes(m.month)&&(m.status==='blocked'||m.status==='difference'||m.unchosen.length||m.notes.length));
   if(m){const section=[...form.querySelectorAll('.pdf-month')].find(s=>s.dataset.month===m.month);section?.scrollIntoView({block:'start'});if(m.unchosen.length)pdfFocus($(`[data-index="${m.unchosen[0]}"] [data-action=pdf-scope]`,form));}
  }else if(e.details?.kind==='pdf_rows')showPdfDiagnostics(form,e.details);else result.scrollIntoView({block:'nearest'});
 }finally{form.inert=false;}
}
const monthlyBaseAction=action;
action=async function(name,el){const form=el.closest?.('#pdf-review-form');switch(name){
 case 'approve-pdf-month':return approvePdfMonths(form,[el.dataset.month]);
 case 'jump-pdf-index':{const row=$(`.pdf-row[data-index="${Number(el.dataset.index)}"]`,form);if(row){const target=$('.pdf-row-diagnosis:not([hidden])',row)||row;pdfFocus(target);}return;}
 case 'add-pdf-missing':{const m=app.pdfReconciliation.months.find(m=>m.month===el.dataset.month),r=m?.missing[Number(el.dataset.missing)];if(!r)return;
  const original=[...form.querySelectorAll('.pdf-row')].find(row=>$('[data-key=source_id]',row).value===r.source_id);
  if(original){original.dataset.excluded='0';original.dataset.exclusionReason='';original.dataset.choice='';}else $('#pdf-rows',form).insertAdjacentHTML('beforeend',pdfRowMarkup(r,Math.max(-1,...[...form.querySelectorAll('.pdf-row')].map(r=>Number(r.dataset.index)))+1,app.intakeJob.pages));
  regroupPdfRows(form);schedulePdfSave(form);return;
 }
 case 'pdf-approved-dashboard':app.suppressDraft=true;closeModal();app.suppressDraft=false;navigate('inbox');return;
 case 'explain-pdf-month':{const box=el.closest('.pdf-month-check'),output=$('.pdf-ai-explanation',box),revision=app.pdfRevision;el.disabled=true;output.textContent='Deine lokalen KIs prüfen die Belege nacheinander. Das kann einige Minuten dauern. Die Rechenprüfung bleibt verfügbar.';
  try{await queuePdfSave(form);const r=await api('/api/intake/pdf-explain',{...collectPdf(form),month:el.dataset.month});if(!output.isConnected)return;output.innerHTML=`<p class="small muted">KI-Vorschläge zur Gegenprüfung · keine automatische Änderung${revision!==app.pdfRevision?' · Liste inzwischen geändert, erneut prüfen':''}</p>${r.answers.map(a=>`<details class="source-details"${a.role==='Koordinator'?' open':''}><summary>${esc(a.role)} · ${esc(a.model)}</summary><p>${esc(a.explanation||a.error)}</p></details>`).join('')}`;
  }catch(e){output.textContent='KI-Hilfe nicht verfügbar: '+e.message+' Die genaue Differenz und Originalprüfung funktionieren auch ohne KI.';}finally{el.disabled=false;}return;
 }
 default:return monthlyBaseAction(name,el);}};
document.addEventListener('input',e=>{const box=e.target.closest('.pdf-override');if(!box)return;app.pdfOverrides[box.dataset.month]={accepted:!!$('[data-override-accepted]',box)?.checked,note:$('[data-override-note]',box).value};schedulePdfSave(box.closest('form'));});

// Numeric/source edits invalidate the prior approval, while preserving the note.
document.addEventListener('input',e=>{if(!e.target.matches('[data-key=amount],[data-key=booked_on],[data-key=page],[data-key=quote],[name=opening_balance],[name=closing_balance],[name=balance_quote]'))return;const form=e.target.closest('#pdf-review-form');if(!form)return;$('[name=checked]',form).checked=false;for(const item of Object.values(app.pdfOverrides||{}))item.accepted=false;for(const control of form.querySelectorAll('[data-override-accepted]'))control.checked=false;});
